-- MP-0009: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0009: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='perikatan-nasional' and type='alliance') then raise exception 'MP-0009: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('mohd-syahir-che-sulaiman','khlir-mohd-nor','ikmal-hisham-abdul-aziz') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0009: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('bachok','ketereh','tanah merah') and slug not in ('mohd-syahir-che-sulaiman','khlir-mohd-nor','ikmal-hisham-abdul-aziz')) then raise exception 'MP-0009: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0009:%' and (m.source_type <> 'editorial' or e.slug not in ('mohd-syahir-che-sulaiman','khlir-mohd-nor','ikmal-hisham-abdul-aziz') or m.import_key not like 'MP-0009:' || e.slug || ':%')) then raise exception 'MP-0009: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mohd-syahir-che-sulaiman','Mohd Syahir Che Sulaiman','opposition','Member of the Dewan Rakyat','Bachok','Kelantan','Mohd Syahir Che Sulaiman represents Bachok, Kelantan, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4064','/portraits/mohd-syahir-che-sulaiman.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P025.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4064"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'khlir-mohd-nor','Khlir Mohd Nor','opposition','Member of the Dewan Rakyat','Ketereh','Kelantan','Khlir Mohd Nor represents Ketereh, Kelantan, in the Dewan Rakyat. Parliament lists affiliation with Perikatan Nasional (PN).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4065','/portraits/khlir-mohd-nor.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P026.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4065"}, {"label": "Parliament · current Dewan Rakyat directory", "url": "https://www.parlimen.gov.my/ahli-dewan.html?uweb=dr"}]'::jsonb from public.entities parent where parent.slug='perikatan-nasional' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ikmal-hisham-abdul-aziz','Ikmal Hisham Abdul Aziz','opposition','Member of the Dewan Rakyat','Tanah Merah','Kelantan','Ikmal Hisham Abdul Aziz represents Tanah Merah, Kelantan, in the Dewan Rakyat. Parliament lists affiliation with Perikatan Nasional (PN).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4066','/portraits/ikmal-hisham-abdul-aziz.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P027.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4066"}, {"label": "Parliament · current Dewan Rakyat directory", "url": "https://www.parlimen.gov.my/ahli-dewan.html?uweb=dr"}]'::jsonb from public.entities parent where parent.slug='perikatan-nasional' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('mohd-syahir-che-sulaiman','khlir-mohd-nor','ikmal-hisham-abdul-aziz') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0009: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0009:mohd-syahir-che-sulaiman:bachok-development-funding','Seek additional federal funding for Bachok’s infrastructure and local economy','Infrastructure',null,null,null,'2026-01-11','https://inforakyat.kelantan.my/index.php/berita/390-yb-syahir-komited-bawa-lebih-banyak-peruntukan-untuk-pembangunan-bachok',null,null,'Mohd Syahir committed to working with ministries and agencies to obtain more development funding for Bachok.','The pledge names infrastructure, basic facilities and support for local economic activity. A comparable allocation target, resulting funding total and completed project set were not verified, so status and completion remain unknown.','2026-11-09','editorial',false from public.entities e where e.slug='mohd-syahir-che-sulaiman' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

